<?php /** @var \Sysfera\Plugin $sf @var \SysferaStoragerent\Ctx $ctx @var string $lang @var array $t @var array $contracts @var array $invoices @var array $payments @var array $balance @var array $requests @var array $docs @var array $units */
require __DIR__ . '/_nav.php'; ?>
<div class="card"><h2 style="margin:0"><?= e($t['name']) ?></h2>
  <p><?= e($sf->t('portal_debt')) ?>: <b class="<?= $balance['debt'] > 0 ? 'bad-t' : '' ?>"><?= e(sr_m($balance['debt'], $lang)) ?></b><?php if (!empty($balance['credit'])): ?> · <?= e($sf->t('pay_credit')) ?>: <b><?= e(sr_m($balance['credit'], $lang)) ?></b><?php endif; ?></p>
  <?php if ($t['restrictions'] !== ''): ?><div class="warn-box"><b><?= e($sf->t('restriction')) ?>:</b> <?= e($t['restrictions']) ?></div><?php endif; ?></div>
<div class="card"><h3><?= e($sf->t('wrms_contracts')) ?></h3><?php if (!$contracts): ?><p class="muted"><?= e($sf->t('none')) ?></p><?php else: ?><table><tbody><?php foreach ($contracts as $k): ?><tr><td><a href="<?= e($sf->url('/contract/' . $k['id'])) ?>"><b><?= e($k['number']) ?></b></a></td><td><?= e(sr_d($k['start_date'])) ?> – <?= e(sr_d($k['end_date'])) ?></td><td><span class="badge <?= e(sr_cls((string)$k['state'])) ?>"><?= e($sf->t('cs_' . $k['state'])) ?></span></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div>
<div class="card"><h3><?= e($sf->t('wrms_invoices')) ?></h3><?php if (!$invoices): ?><p class="muted"><?= e($sf->t('none')) ?></p><?php else: ?><div class="sr-scroll"><table><thead><tr><th><?= e($sf->t('col_invoice')) ?></th><th><?= e($sf->t('col_due_date')) ?></th><th class="r"><?= e($sf->t('col_total')) ?></th><th class="r"><?= e($sf->t('col_outstanding')) ?></th><th><?= e($sf->t('col_status')) ?></th></tr></thead><tbody>
<?php foreach ($invoices as $i): ?><tr><td><a href="<?= e($sf->url('/invoice/' . $i['id'])) ?>"><b><?= e($i['number']) ?></b></a></td><td><?= e(sr_d($i['due_date'])) ?></td><td class="r"><?= e(sr_m($i['total'], $lang)) ?></td><td class="r"><?= e(sr_m($i['outstanding'], $lang)) ?></td><td><span class="badge <?= e(sr_cls($i['status'])) ?>"><?= e($sf->t('st_' . $i['status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
<div class="card"><h3><?= e($sf->t('wrms_payments')) ?></h3><?php if (!$payments): ?><p class="muted"><?= e($sf->t('none')) ?></p><?php else: ?><table><tbody><?php foreach ($payments as $p): ?><tr><td><?= e(sr_d($p['pay_date'])) ?></td><td><?= $p['kind'] === 'payment' ? e($sf->t('pm_' . $p['method'])) : e($sf->t('pay_refund')) ?></td><td class="r"><?= e(sr_m($p['amount'], $lang)) ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div>
<div class="card"><h3><?= e($sf->t('wrms_requests')) ?></h3>
  <?php foreach ($requests as $r): ?><p><b><?= e($r['title']) ?></b> <span class="badge <?= e(sr_cls((string)$r['status'])) ?>"><?= e($sf->t('rq_' . $r['status'])) ?></span><br><small class="muted"><?= e(sr_dt((int)$r['created_at'])) ?></small></p><?php endforeach; ?>
  <form method="post" enctype="multipart/form-data" action="<?= e($sf->url('/portal/request')) ?>" class="sr-form"><?= csrf_field() ?><h4><?= e($sf->t('portal_new_request')) ?></h4><?= sr_in('title', $sf->t('rq_title'), '', 'text', 'required maxlength="190"') ?><?= sr_area('body', $sf->t('rq_body'), '', '', 3) ?>
    <?= sr_sel('unit_id', $sf->t('col_unit'), [0 => '—'] + $units, 0) ?><label class="fld"><span><?= e($sf->t('util_photo')) ?></span><input type="file" name="photo" accept="image/*"></label><button class="btn primary"><?= e($sf->t('portal_send')) ?></button></form></div>
<?php if ($docs): ?><div class="card"><h3><?= e($sf->t('wrms_documents')) ?></h3><table><tbody><?php foreach ($docs as $d): ?><tr><td><a href="<?= e($sf->url('/doc/' . $d['id'])) ?>"><?= e($d['title']) ?></a></td><td><?= e(sr_dt((int)$d['created_at'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
